-- ============================================================================
-- Le roumain des données : carte, sujets, tâches, et le thésaurus proposé à la FICEDL
--
-- Chantier « locale ro », reste du lot 3 (backlog E39, DOC-I18N-5). Le lot 3
-- (20261014192932) a mis ro dans les sources ; les données en base retombaient
-- sur leur langue de repli. Traductions faites le 14/10/2026 depuis le français
-- relevé en production (lecture seule), pas encore relues par une personne
-- roumanophone (voir docs/journal/references/RELECTURE_roumain_2026-10-14.md).
--
-- Chaque UPDATE n'écrit ro que là où il manque, et seulement si le français
-- traduit est encore celui qui a été relevé (empreinte ou égalité) : une ligne
-- retouchée depuis garde sa langue de repli plutôt qu'une traduction fausse.
-- Rejeu depuis zéro : seul le thésaurus a des lignes (données de référence,
-- 461 propositions posées) ; carte, sujets et tâches n'existent qu'en
-- production, où leurs UPDATE trouvent leurs lignes (0 ailleurs).
-- Les déclencheurs touchent updated_at (carte, sujets) : c'est une modification.
--
-- Thésaurus FICEDL (THES-FIC1, THES-FIC6) : les libellés de la source restent
-- TELS QU'ASPIRÉS dans labels — aucune ligne n'y est écrite. Le roumain va dans
-- une colonne neuve, labels_proposes : les traductions qu'AnarBib propose à la
-- FICEDL dans les langues que la source n'a pas. Le sync
-- (scripts/ficedl_thesaurus_sync.mjs) ne la connaît pas et ne l'écrase donc
-- jamais ; à l'affichage, labels l'emporte (src/lib/i18nLabel.js,
-- libellesFicedl). Quand la source publiera son roumain, il arrivera dans labels
-- et la proposition cessera d'être lue.
-- ============================================================================

ALTER TABLE public.ficedl_thesaurus_terms
  ADD COLUMN IF NOT EXISTS labels_proposes jsonb NOT NULL DEFAULT '{}'::jsonb;

COMMENT ON COLUMN public.ficedl_thesaurus_terms.labels_proposes IS
  'Traductions proposées par AnarBib à la FICEDL, dans les langues absentes de la source ({"ro": "…"}). Jamais écrites par le sync ; labels (tels qu''aspirés) l''emporte à l''affichage. THES-FIC6.';

-- ── Carte (187 fiches) : le nom propre ne se traduit pas ─────────
UPDATE public.cartography_entries c SET
  name_i18n    = c.name_i18n || jsonb_build_object('ro', c.name_i18n->>'fr'),
  city_i18n    = CASE WHEN v.ville IS NULL THEN c.city_i18n    ELSE c.city_i18n    || jsonb_build_object('ro', v.ville) END,
  country_i18n = CASE WHEN v.pays  IS NULL THEN c.country_i18n ELSE c.country_i18n || jsonb_build_object('ro', v.pays)  END,
  notes_i18n   = CASE WHEN v.note  IS NULL THEN c.notes_i18n   ELSE c.notes_i18n   || jsonb_build_object('ro', v.note)  END
FROM (VALUES
  ('03a8e0ec-8247-4e76-8632-319fb425a163', 'Roma', 'Italia', 'Librărie + centru de documentare anarhist, cartierul San Lorenzo, din 1979-81. ATENȚIE: domeniul libreriaanomalia.org pare compromis (spam) — folosește pagina de Facebook.', 'ca25c7c7aa6e77b700ee57d58a280c35'),
  ('03d5d383-c417-4dbd-b890-3e9deef48d08', 'Paris', 'Franța', 'Bibliotecă socială a Groupe Libertaire La Rue (grupul Louise-Michel), anarhism social. Loc de întâlniri, dezbateri și conferințe ale grupului. „La Rue” este și titlul unei reviste publicate de grup între 1967 și 1986 (37 de numere), în curs de digitalizare.', '416757fb98064606fd25dccf7f05f63d'),
  ('040ffdef-6202-448e-bb80-c492a85094af', 'Cluj-Napoca', 'România', 'Platformă de arhivă digitală dedicată documentării istoriei puțin cunoscute a pătrunderii și răspândirii ideilor anarhiste în România începând cu secolul al XIX-lea. Peste 600 de piese inventariate: broșuri, afișe, reviste, fanzine, portrete (Eugen Relgis, Gheorghe Levezan, Nikolai Sudzilovsky), corespondență, ediții. Publică regulat Buletinul Anarhivei (din 2021). Colecție notabilă: zine-uri din secolul al XXI-lea (2001-20xx); expoziție inaugurală: „Din istoria anarhismului în România (sec. XIX)”. Întreține o listă îngrijită de arhive anarhiste internaționale (FICEDL, Kate Sharpley Library, FAL, CIRA etc.) — integrare explicită în familia arhivistică libertară internațională. NOTĂ: arhivă integral digitală, fără spațiu deschis publicului; punct cartografiat la Cluj-Napoca. Sursă: anarhiva.com.', '7846a7a89529683dc3cd15b5a0d84934'),
  ('05265de3-3595-4269-99d2-7f21d834a06c', 'Montevideo', 'Uruguay', 'Ateneu libertar din Montevideo, spațiu de întâlniri și de difuzare.', '8841aee5dddbbc40e8203c405fdcfad9'),
  ('05a2e71d-0cd6-4906-b2e6-b4f837bc79c4', 'Seattle', 'Statele Unite', 'Librărie-colectiv anarhistă în Pike Place Market din Seattle, fondată în 1973 (desprinsă din Red and Black Books). Administrată colectiv de persoanele care lucrează acolo, fără șefi, decizii prin consens. Peste 10 000 de cărți, ~70 de secțiuni (anarhism, studii queer/trans, feministe, afro-americane, indigene, latinx, ecologie...). Sprijină programul Books to Prisoners. Deschisă 7/7. Sursă: site oficial + Pike Place Market + Yelp (activă în mai 2026).', 'd7a2261b0b38792c9b3e78482f91bc15'),
  ('06f656cd-f633-4d5e-83ae-07f710096085', 'Santa Cruz de la Sierra', 'Bolivia', 'Casă-soră a Mujeres Creando la Santa Cruz de la Sierra, deschisă în jurul anului 2012 și relansată în 2019. Restaurant, cafenea, librărie, spațiu politic anarha-feminist („mai mult feminist decât cultural”, după Greta Vargas). Găzduiește oficina socio-legal Mujeres en Busca de Justicia (asistență juridică gratuită în fața violenței machiste). Spațiu explicit liber de cenzură, machism, rasism și homofobie. Deschis tinerilor din grupurile universitare și femeilor aflate în proces de construire a autonomiei.', '0c7e795ed45bd6370f059d5660d70879'),
  ('06f74323-8aa9-45a4-b9ba-7cbca84d5e01', 'Parma', 'Italia', 'Bibliotecă libertară la Parma.', '46c0b2eb789bae8f5021b1f25f9764a5'),
  ('0871f5b8-1634-401d-a67f-fa993c15146b', 'Lyon', 'Franța', 'Editură și centru de resurse libertar, Lyon.', 'fd016b51470cbff21b3449cb4c68dc0f'),
  ('097a78e7-a1ac-497b-afe9-d18becc733cf', 'Gent', 'Belgia', 'Arhivă anarhistă din Gent, împarte clădirea centrului ''t Assez cu Infotheek (consultarea fondurilor prin intermediul acesteia, la cerere la anarchief@ymail.com). Probabil cea mai mare arhivă anarhistă din Belgia. Fondată în 1990 de Zwart & Rood vzw, distribuție anarhistă, după achiziționarea unei biblioteci private. Circa 5000 de piese: cărți, broșuri, periodice, cataloage ale editurilor anarhiste, afișe și arhive în sens strict (procese-verbale, corespondență, pamflete, cărți poștale). Acoperă circa 3/4 din publicațiile anarhiste în neerlandeză; a integrat în 2011 arhivele de periodice ale CPCA francez. Zusterarchief cu AAA (Appelscha, NL); parteneriate cu CIRA Geneva, AGA bib Amsterdam. Fără împrumut. Surse: anarchief.be, anarchy.be/anarchief, cageweb.be (ANARC).', '87976e2604a7c96c8234312d27c06f31'),
  ('09909a8b-41cb-48ee-8283-7a3424b3e7cb', 'Londra', 'Regatul Unit', 'Infoshop autogestionat și arhivă, Walworth, sudul Londrei. Din 1991.', 'ab43f8ea11f97c903c2c01367188c3f2'),
  ('09db15b6-e591-4289-ad70-6ab7220d24b3', 'Valparaíso', 'Chile', 'Bibliotecă anarhistă și antiautoritară din Cerro Lecheros, Valparaíso. Inclusă de colectivul La Peste (februarie 2023) printre bibliotecile populare și antiautoritare din regiune. Deschisă marțea 16-19h. Activitate în 2026 confirmată (jornada „Con el Punky Mauri en la memoria”, 7 mai 2026, în colaborare cu Biblioteca Anárquica Sebastián Oversluij Seguel). Memorie combativă: omagii regulate pentru Mauricio Morales, Santiago Maldonado și solidaritate cu compañerxs din închisoare. IG @baclevalpo.', '630e077718726ddbb333280c0c223678'),
  ('0a8158a3-4c9c-4114-960d-698f009631f0', 'Zagreb', 'Croația', 'Bibliotecă-infoshop în Autonomous Cultural Center Attack!, instalat într-o fostă fabrică de medicamente. Numită după personajul Pippi Șosețica (Pippi Långstrump). Deschisă marți și joi 17-20h, ciclul literar ProezLotta sâmbăta 17-19h. Toleranță zero față de fascism/sexism/rasism/homofobie. Organizează Zagreb Anarchist Bookfair (a 14-a ediție în 2018).', '12153cd764f6cbf77b55616d2236ffd7'),
  ('0da0f76c-a82a-46c0-b56a-29fe3734018f', 'Reggio Emilia', 'Italia', 'Arhivele Camillo Berneri. Fond major despre anarhismul italian și exil.', '665f3b87a2f2b90aac1bb3d33e1cf113'),
  ('0dcd1306-3365-44eb-935c-a2a7741eb268', 'Santiago', 'Chile', 'Fond documentar al anarhismului din regiunea chiliană. Deschis miercurea 17h-21h la Casa Anarquista La Termita.', '108ce2dde6be39d00c48a8252510714b'),
  ('104eed47-7e95-405f-9219-7dced71d8ccb', 'Asti', 'Italia', 'Centru de documentare libertar, rețeaua RebAL.', '5a9f877ae28a04f5c0e289f560fa2118'),
  ('10d7e1fe-ce4b-4c1f-aa4f-92fee8511fb8', 'Gent', 'Belgia', 'Bibliotecă anarhistă din Gent, la etajul 1 al centrului ''t Assez. Circa 3000 de cărți care pot fi împrumutate (împrumut gratuit, garanție 3€/carte, 3 săptămâni), un fond larg de periodice naționale și internaționale și de broșuri, care pot fi consultate pe loc la o cafea. Teme: anarhism, squat, antimilitarism, feminism, drepturile animalelor, ecologie, economie, drept și represiune, mondializare, antiglobalizare, acțiune directă. Lucrează complementar cu Anarchief pentru periodice. Membră a FICEDL (cod G-IN 0022). Program: miercuri 16-21h, vineri 19-21h, sâmbătă 14-17h. Surse: acgent.org, anarchie.be/infotheek, placard.ficedl.info.', '34db55edb3be280dca464f336441ee41'),
  ('117d719e-e8d6-4858-a9f9-5b4d13685233', 'Londra', 'Regatul Unit', 'Arhivă, resursă și refugiu (safe haven) pentru mișcările sociale, culturile experimentale și marginale și istoriile lor. Colecții cu o puternică componentă libertară: Anarchism, Anarcho-Punk, Anti-Apartheid, Squatting, autonomism, contracultura italiană, presa underground, ecologie radicală, Eco-Action (cu finanțare National Lottery Heritage), Algerian Resistance Newspapers, Underground Techno Scene, East London Big Flame, Worker Photographer. Deschisă publicului miercuri-vineri 11h-18h, fără programare. Oferă un spațiu gratuit de organizare și de evenimente grupurilor activiste și de educație autogestionată. Practică și teoretizează „archiving from below” printr-un grup de lectură dedicat. Tot materialul sub licență Creative Commons BY-NC-SA 4.0. Sursă: maydayrooms.org.', 'a7fc9d3b8efa8632bda04110fbc7fc19'),
  ('15c355d6-b2ef-4ca9-98fd-5588aa2a39e3', 'Ancona', 'Italia', 'Arhiva națională a Unione Sindacale Italiana (USI-AIT), sindicat anarho-sindicalist italian afiliat la Asociația Internațională a Muncitorilor (AIT).', '416dca8ab434da50ebbdb58335331c8e'),
  ('15d2a99c-120a-4b02-8133-030e49117785', 'Rio de Janeiro', 'Brazilia', 'Arhivă a mișcării muncitorești (inclusiv fonduri anarhiste), afiliată universității.', '9ce986490ce7e5c63b383bd10d236cef'),
  ('1b725b7d-e359-4d33-8766-039f12d1f171', 'Brighton', 'Regatul Unit', 'Centru social anarhist autogestionat și cooperativ, deschis în 2003. Bibliotecă radicală, librărie, cafenea vegană, bar pentru membri, sală de concerte. Cursuri gratuite de engleză pentru persoanele migrante. Numit după Harry Cowley, militant local. 100% voluntariat, fără scop lucrativ.', '17110e7df5bb193061a74506399997e9'),
  ('1d439b68-cb9a-41a9-829d-7b9918b22c3b', 'Milano', 'Italia', 'Ateneo Libertario activ la Milano, găzduit în aceeași palazzina cu Circolo Ponte della Ghisolfa și Federazione Anarchica Milanese. Administrează Archivio proletario internazionale (a nu se confunda cu Ponte, de care este separat structural — precizare făcută de colectivul însuși în mai 2026).', '2a1773db31b820918b08b6172795bd7d'),
  ('1e04c547-c18f-4aa9-8f37-24f6b0d6390b', 'Guasila', 'Italia', 'Arhivă și bibliotecă libertară sardă (în sardă campidaneză: „Arkiviu bibrioteka”), la Guasila, în memoria lui Tommaso Serra. Fond editorial important.', 'f3295f13b2efeac9a004abf59d017b29'),
  ('1ece3e2d-7d46-47e5-a75a-aaf1023c0e66', 'Genova', 'Italia', 'Spațiu de documentare la Genova.', 'cfa757545f193bd7c744f2b8a05a964d'),
  ('1f3bb96a-3f57-4e25-a55b-c946bd8bb283', 'Budapesta', 'Ungaria', 'Bibliotecă anarhistă („Bătrâna Cârtiță”) și infoshop, pe aceeași stradă cu centrul cultural Auróra, dar distinctă de acesta. A organizat primul Budapest Anarchist Bookfair (septembrie 2025). Fond în maghiară și engleză (în special Active Distribution), broșuri anarhiste și non-bolșevice.', '87e84ba366a7e16ba4cbf54cb29cccce'),
  ('216d00a3-ac13-4f26-b9da-2860da289d19', 'Paris', 'Franța', 'Bibliotecă anarhistă pariziană, loc de întâlniri și de lecturi.', 'f49076f39669ec040da446acf959abd0'),
  ('2412a2f3-3c8f-4fdf-9ee7-c3798869d223', 'Porto', 'Portugalia', 'Librărie-bar asociativă, spațiu cultural libertar la Porto.', '7fea87cf39a7b289658cc180d2952128'),
  ('25d4cc6c-ee63-4a33-9310-aa41545453f6', 'Castel Bolognese', 'Italia', 'Bibliotecă libertară de referință în Emilia-Romagna.', '2fe5aec91289abf81ad7a4a43c23ee6b'),
  ('27c3220d-69c4-470c-af29-3af9064a13fd', 'Bologna', 'Italia', 'Arhivă de istorie a mișcărilor sociale la Bologna.', '05853bd84603e3156b9f7b481d32a57b'),
  ('281dc98e-cdc4-4983-bcac-9ff1fd7d8012', 'Barcelona', 'Spania', 'Ateneu libertar din Gràcia, în continuitatea Ateneului istoric (1976-2002, care se afla pe carrer Perill 52). Găzduiește Biblioteca la Malcrià, bibliotecă colectivă, precum și Edicions Malcriàs. Activități săptămânale: tertúlies llibertàries, cinefòrum, microfon deschis.', 'ddde09343f4262e1f0dfb7ebba2718a7'),
  ('2969e35a-8d7f-4ac1-a168-96fdd3aa6992', 'Viena', 'Austria', 'Bibliotecă și arhivă anarhistă, literatură libertară în numeroase limbi.', '375782416df01939f9bdee77df462cc7'),
  ('32f0116f-823c-419d-a447-b3d99ad72616', 'Viena', 'Austria', '~4000 de cărți. Arhivă a mișcărilor sociale din 2004.', '43bda327eeceb4cebd19a59823930167'),
  ('337b7b65-602d-4b61-aa84-8622a4c70cd3', 'Valencia', 'Spania', 'Ateneu libertar din València fondat în martie 1986 (inițial pe carrer Baix, apoi Palma 3 din 1998). A sărbătorit 40 de ani de activitate în 2026. Editează revista Al Margen, organizează cineforumuri, prezentări de carte, dezbateri. Biblioteca Oberta săptămânală.', '60be179789b59fe5bc743afd7b7979c3'),
  ('345b2178-14e7-4d19-8e74-c3b7418c6d8c', 'Philadelphia', 'Statele Unite', 'Librărie anarhistă colectivă, bazată pe voluntariat, din 1976.', '4230ede1e2897004e29f27fb38b42538'),
  ('3571e5d5-9c0e-4e54-a181-9d5d99919f2a', 'Nantes', 'Franța', 'Colecții de cărți/broșuri/periodice ale Librairie du Monde libertaire, care pot fi consultate la CHT.', '1401eb2fc50f7f4178609ecd471f7fa3'),
  ('36a6a25c-7928-4dd1-ad90-67e234f03c93', 'Rosario', 'Argentina', 'Arhivă și bibliotecă anarhistă din Rosario, fondată în 1946. ~3000 de cărți, hemerotecă, librărie.', '57b2f65f97de821a0af182872ab385e7'),
  ('371f6234-cc78-454f-b345-2e8430fd4cb4', 'Bologna', 'Italia', 'Librărie de mișcare și cafenea, moștenitoare a librăriei „Il Picchio”. Presă de mișcare, fond anarhist și libertar.', '658061285b61653a94404806b9b95479'),
  ('3749d8b6-a3bb-464d-8eda-bd4d45fa7800', 'Londra', 'Regatul Unit', 'Fondată la Brixton în 1979. Colecția fizică transferată în California în 1999; adresă poștală în UK păstrată.', 'a11f3b8858748bf710b6c628cdffc363'),
  ('3a56107d-8ee7-4910-be5c-268af27b7110', 'Nottingham', 'Regatul Unit', 'Bibliotecă și arhivă libertară din Nottingham, fonduri extinse.', '05930b912b066926a05cc75031414d69'),
  ('3a73ca74-49f6-4a38-b1f7-7cc5743213d4', 'Wellington', 'Noua Zeelandă', 'Infoshop anarhist, distribuție de cărți și de presă militantă.', '608141914c43172a26c2ce80be36383f'),
  ('3b88509c-175a-40fb-869c-d7fc7d18c9bc', 'Valparaíso', 'Chile', 'Spațiu comunitar teritorial autogestionat într-o fostă capilla (1890) din Cerro Cordillera, fondat în 2008 de Taller de Acción Comunitaria (TAC, +30 de ani de experiență). Reunește peste 30 de organizații vii din cerro. Biblioteca Comunitaria inclusă de La Peste printre bibliotecile antiautoritare din Valparaíso. NOTĂ: spațiu mixt, nu strict libertar — parteneriate instituționale cu MINCAP, Muzeul de istorie naturală, primăria (alcaldesa Camila Nieto, Frente Amplio). Componenta antiautoritară este purtată de unele dintre organizațiile sale membre. Foarte activ (site actualizat în mai 2026).', '18927cc91db57ed8708c5487f3cb3f32'),
  ('3dc06022-78bf-4ac4-b08d-d9f40f86ad23', 'Tel Aviv-Jaffa', 'Israel/Palestina', 'Bibliotecă radicală antiautoritară și spațiu de întrajutorare al colectivului Culture of Solidarity, în House of Solidarity (Beit Romano, complexul Teder). Moștenitoare a istoricului Salon Mazal (infoshop anarhist din Tel Aviv, astăzi închis). Fond radical, ateliere, conferințe, distribuiri de alimente, sprijin pentru persoanele care solicită azil; organizează Târgul anarhist de carte Jaffa-Tel Aviv (prima ed. 2022, a 2-a ed. 2023). Spațiu vegan, antirasist, antisexist, antitransfob. Se definește drept o „insulă” pentru discursul politic radical în Israel-Palestina. NOTĂ: activitate confirmată până în februarie 2024 (post-7oct2023) — continuitatea trebuie verificată, dat fiind contextul. Surse: 972mag, Freedom News, Secret Tel Aviv, anarchistbookfair.me.', 'c89570c9e6b4fbe999ec34440f202be0'),
  ('3de2963b-2e48-4dbb-abaf-b18a8b12e277', 'Wellington', 'Noua Zeelandă', 'Cel mai vechi infoshop anarhist activ din Noua Zeelandă, fondat la 1 mai 1995. Te Whanganui-A-Tara / Wellington. Găzduit succesiv la Cake Shop (Cuba St), Oblong (Te Aro), apoi Trades Hall (Vivian St), apoi Opportunity for Animals (Riddiford St), iar din mai 2023 în Book Haven, pe aceeași stradă. Deschis 7 zile din 7, 10h-17h. Stoc: cărți anarhiste, feministe, indigene, ecologiste, zine-uri, insigne, tricouri, patch-uri. Publică Aotearoa Anarchist Review (AARGH!) și agenda militantă Plan B (în parteneriat cu Wellington ZineFest). Filme și dezbateri la 13 Garrett Street, Te Aro. Legături strânse cu Indymedia Aotearoa și 128 Community Centre.', 'e7ab67d90de0ec207d9f978bd7f2eb7a'),
  ('3ef479fe-49bc-4534-a74f-841d2aec9420', 'Berlin', 'Germania', 'Librărie colectivă autogestionată libertară, fondată în 1980 în Mehringhof (Kreuzberg). Filială deschisă în 2002 în Prenzlauer Berg (Kastanienallee). Fond: politică, filozofie, anarhism, mișcări sociale, istoria NS. Coeditoare a Verlag Assoziation A. Lecturi și dezbateri regulate.', 'a6cf6640b23ad5cda40f25486d1c76c0'),
  ('3fbd4123-e880-4a88-a3fb-c9fd6018f795', 'Vancouver', 'Canada', 'Librărie, infoshop și centru de resurse non-profit din Vancouver, administrat de un colectiv de voluntari/voluntare din 1973 — unul dintre cele mai vechi din America de Nord. Include o bibliotecă de împrumut, o bancă de semințe, un free store (născut din Free Market al Occupy Vancouver 2011), internet gratuit. Secțiuni anarhie, studii queer, feminism, teorie radicală, Primele Națiuni, închisori. A supraviețuit unui incendiu în 2004 și mai multor mutări (gentrificare). Adresa actuală: Commercial Drive (din 2022). Sursă: site oficial + Wikipedia + Vancouver Guardian.', '20934c1c9e31254bfb5c8d760caebf21'),
  ('442cd4da-1428-4c2d-bcb3-29de81c24e07', 'San Francisco', 'Statele Unite', 'Librărie anarhistă colectivă din Haight-Ashbury.', '0f72b9f2ff6a372dee608457ae3a6729'),
  ('456fcb5c-e80e-48af-9107-e73b1bcae29a', 'Madrid', 'Spania', 'Local anarhist cu biblioteca socială Enoch.', '14389b0951007723af0f261bb27808a5'),
  ('4650c080-ad8e-430b-b9b7-3580190bedc4', 'Modena', 'Italia', 'Bibliotecă populară și arhivă a Circolo Anarchico La Scintilla, numită după Ugo Fedeli, militant și istoric al anarhismului italian.', '15294ce23214b8192575cc45c7165a7b'),
  ('47660774-683b-43e1-9cae-b9457996a71a', 'Trieste', 'Italia', 'Grup anarhist din Trieste, membru al Federazione Anarchica Italiana. Editează revista Germinal (nr. 137 apărut în mai 2026). Cuprinde Biblioteca Sociale Umberto Tommasini (anarhist italian care a luptat în Spania 1936-39) și Centro Studi Libertari. Permanență joia 18h-20h, deschis și marțea și vinerea 19h-21h. Loc împărțit cu Non una di meno Trieste, Smarza Pride și alte colective.', 'fb17b57d58318fd6532b6554e35b2cfd'),
  ('479ce5f6-22c6-4aaa-96e1-98ba48cef5d0', 'Milano', 'Italia', 'Arhiva Primo Moroni, librăria Calusca și centrul social COX18 din Milano. Arhivă de referință a mișcărilor sociale și a contraculturii anilor 1970-1990, în memoria lui Primo Moroni (autor al L''Orda d''oro).', '2ca16c0144379b2ad9814a32b8d08e12'),
  ('4b36d6a6-27f6-4ba0-89d7-1d0d0caf1155', 'Lleida', 'Spania', 'Bibliotecă anarhistă din Lleida, fondată în septembrie 2017. ~3000 de cărți, reviste, fanzine și documente. Catalog online în Koha (cataleg.bibliotecamariarius.org). Spațiu de lectură, corespondență cu persoanele încarcerate, sală pentru colective. Program: marți și miercuri 17h-21h. Numită după Maria Rius, militantă anarhistă catalană din anii 1920-1930.', 'adc7d15d4b8c6ba0ed87bd15fd1f6f08'),
  ('4b6650a8-a706-47e5-a1c5-c01472f83908', 'Nantes', 'Franța', 'Serviciul de arhive al Fédération Anarchiste.', 'a43798fdb2393db75f30a14c1f6ea86f'),
  ('4d74a2be-b5af-4f13-9e09-9575890c7d7f', 'Paris', 'Franța', 'Bibliotecă anarhistă: împrumut de cărți fără bariera banilor, arhive, infokiosk de broșuri și fluturași. Permanență marțea 17h-20h, discuții și întâlniri joia. Metrou Belleville / Colonel Fabien.', 'd2d5332cb7ec36849bfa5cfe589504b3'),
  ('4f386e79-11e3-408a-a636-557a47617f60', 'Atena', 'Grecia', 'Bibliotecă anarhistă din Atena.', '9793be268a2f7a1533f96a6ae264019a'),
  ('4fb398cf-7668-4609-984a-ae8156349f2a', 'Montreal', 'Canada', 'Librărie anarhistă și infoshop, cărți și fanzine în franceză și engleză.', 'a208d536c9f573785a7e36bd1d86d0f3'),
  ('52270b8d-2061-4757-b4b8-9016c5442ed7', 'Milano', 'Italia', 'Unul dintre cele mai vechi și mai active cercuri anarhiste din Italia, fondat la 1 mai 1968 în jurul lui Giuseppe Pinelli. Locul de naștere al revistei A-rivista în 1970. Aceeași adresă (Viale Monza 255) găzduiește și Federazione Anarchica Milanese și Ateneo Libertario Milano, care administrează Archivio proletario internazionale (fișă separată). Foarte implicat în memoria lui Pinelli și Valpreda (strage di piazza Fontana).', '539b0a4836633efbaf0f28c5e59818a5'),
  ('5b503e2f-0363-4534-9e9c-7cf482751d9b', 'Bellinzona', 'Elveția', 'Bibliotecă libertară din Ticino, rețeaua RebAL.', 'c5b09736e6bc8b340af6aaffb0342d78'),
  ('5c3a5bb2-0bf5-4d29-b7e8-eb728fb2e4da', 'Trieste', 'Italia', 'Bibliotecă membră a rețelei RebAL.', 'cd359b4ea7557b5af1a98470fc6cbfe0'),
  ('5dd4dc80-8798-4329-bbb4-8546f041bfca', 'Buenos Aires', 'Argentina', 'Bibliotecă anarhistă din Buenos Aires, punct de distribuție al rețelei anarquista.info și al ziarului Gatx Negrx (Periódico Anarquista de Agitación Cotidiana). Prezență online voit discretă.', '14e28a240b547f9cb216d485655ebb28'),
  ('60eff73d-cdd8-4546-bbd4-81ea7d0448ec', 'Lausanne', 'Elveția', 'Fondat în 1957. ~18 000 de cărți, 4000 de titluri de periodice. Administrează site-ul FICEDL din 2021.', '0cc316552728c4728d21f3ef894b4fea'),
  ('61fb8abf-9cd1-4a23-b3de-aa41f6725686', 'New York', 'Statele Unite', 'Arhivă deschisă a culturii mișcărilor sociale (afișe, zine-uri, ephemera).', '122258c1e78001cbf828096c9349273d'),
  ('62fc3c95-7976-4d6e-bfdc-579ae9e166ff', 'Denver', 'Statele Unite', 'Bibliotecă asociativă de zine-uri fondată în 2003. ~20 000 de zine-uri independente — una dintre cele mai mari colecții din America de Nord. Împrumut de până la 5 zine-uri pentru 3 săptămâni. Găzduită din 2024 în cadrul Bob Ragland Branch a Denver Public Library (ArtPark). Deschis sâmbăta 10h-17h. Organizează anual Denver Zine Fest.', '8e32d6cd89bb0c59836f111afcb89166'),
  ('63aded68-8033-4eb3-aa8d-30dcfeea138a', 'Bogotá', 'Columbia', 'Librărie anarhistă, punk și contraculturală fondată pe 5 august 2014 de Marcos Sosa, în cartierul Chapinero. Nume inspirat de poemul lui Aldo Pellegrini („valiza de foc”). Catalog specializat în anarhism, situaționism, science-fiction, filozofie politică critică. Distribuie fanzine, autocolante, insigne, proiecte editoriale locale și colaborative. Cafenea-librărie cu patio și program de evenimente militante. Editură asociată (Editorial Valija de Fuego). O a doua adresă la Puente Largo (Transversal 59 #106-21). Deschisă luni-joi 10h-20h, vineri-sâmbătă 11h-21h, duminică 10h-17h.', 'a03b82d7685d04da1368ad0c078e8a02'),
  ('6542002a-133c-4aef-aaae-a6b57b5f3acc', 'Zagreb', 'Croația', 'Librărie colectivă și editură („Ce citești?”), moștenitoare a Zagreb Anarchist Movement (ZAP), activ între 1991 și 2001 în umbra războaielor iugoslave. Începe ca editură în 2001, librărie fizică permanentă din 2011. Orientare explicită: anarhism, economie, educație, studii de gen, media, tehnologie, artă, istorie, literatură. Fondul autoeditat păstrează un spirit anarhist puternic. Deschis 10h-20h.', '8b29eaa075c01a09d3839f0f36ffa12c'),
  ('668446de-714f-4ea1-a54d-d38691dda4f9', 'Oaxaca de Juárez', 'Mexic', 'Librespacio cultural și restaurant autogestionat în Oaxaca, de peste 10 ani, specializat în editurile independente din Mexic. Punct de distribuție pentru Ediciones La Social (editură anarhistă, Red de Estudios Históricos del Anarquismo en México) și alte edituri libertare. Prezentări de cărți, cinema, expoziții, ateliere, alimentație bio locală. NOTĂ: librărie culturală independentă apropiată de mediile libertare (nu anarhistă propriu-zis) — caz analog cu La Valija de Fuego (Bogotá). Sursă: SIC Cultura (actualizat august 2025) + Ediciones La Social + site oficial.', 'dae76284927a11bf9139e87f1fbd1a6e'),
  ('6719cafb-5a6e-46a2-841a-2d2ede14d7ac', 'Wrocław', 'Polonia', 'Bibliotecă liberă („Wolna Biblioteka”), susținută de Federația Anarhistă din Wrocław. Fond despre anarhism, antiglobalizare, ecologie, feminism, mișcări sociale, contracultură. Originale de zine-uri, ziare și periodice rare. Permanențe luni 18-20h, marți 17-19h, miercuri 19-20h, joi 17-19h. Activă 2026 (Anarchistyczna majówka 1-2 mai).', 'e3c71c973b4b898c54d7c0be60ea264a'),
  ('672b8818-1fc5-46f6-95d9-ad7442104d8b', 'Bordeaux', 'Franța', 'Ateneu libertar istoric din Bordeaux, bibliotecă și spațiu de întâlniri.', 'e2b4b97217de6a43bbc1f7ed45a5f539'),
  ('69b45b9e-744e-4501-a080-eb0cea1a5b4d', 'Marseille', 'Franța', 'Fondat în 1965. Câteva mii de cărți, broșuri, arhive, afișe. Membru fondator al FICEDL.', 'd6da8d53dbc61851a8bf269d76d4b910'),
  ('69fadd66-f920-4ea4-9f76-0269e9a54069', 'Amsterdam', 'Țările de Jos', 'Bibliotecă anarhistă a Grupului Anarhist din Amsterdam.', '8be1b8929c1f831bb65fd0e0da49b353'),
  ('6a0837bc-7b7b-490f-a5fa-37e77f8f2da1', 'Guadalajara', 'Mexic', 'Centru de documentare și bibliotecă anarhistă, cerc de studii despre istoria și gândirea libertară.', 'c67c6ed02d6052f527ee009397b18c3f'),
  ('6b5f3ac9-32cc-48a0-ad02-6899135716d2', 'Bologna', 'Italia', 'Bibliotecă și sală de studiu Elio Xerri, găzduită în Circolo Anarchico Berneri (spații concesionate în 1968-69, cassero de la Porta Santo Stefano). Catalog în Koha prin rețeaua RebAL (ola.bida.im). Co-organizează Bologna Anarchist Bookfair.', 'f87535359ea7b2f09eaf36a8abc79a05'),
  ('6ed17783-de63-472a-b6ff-fbc03a776237', 'Saint-Imier', 'Elveția', 'Centru cultural libertar în Saint-Imier, leagănul anarhismului (Congresul din 1872).', '8a45c3dfb285d76df0d2727ce67ba1e5'),
  ('6f019f0b-83f1-4b7d-82a7-31d6f728e603', 'Ljubljana', 'Slovenia', 'Centru social anarhist deschis în martie 2006 în clădirea Hlev („Grajd”) din Autonomous Cultural Center Metelkova mesto. **Împlinește 20 de ani în 2026.** Bibliotecă anarhistă în creștere continuă (cărți, reviste, ziare, fanzine), arhivă materială (afișe, steaguri, autocolante), acces liber la internet, spațiu de lectură. Găzduiește Federacija za anarhistično organiziranje (FAO) și Anarho-feministična iniciativa (AFI). Program regulat: mese vegane marțea, infokafan vinerea. Partener al festivalului feminist-queer Red Dawns (Rdeče zore) de la înființarea acestuia.', 'e1575adc8ff26e29ca79f359bc6f6203'),
  ('6fead24c-e575-4a91-8376-d7b864dc2e28', 'Barcelona', 'Spania', 'Ateneu libertar din Poble Sec, activ din 1977. Lansează la vremea lui Ona Lliure (primul radio liber din Barcelona, 1978) și duce numeroase proiecte: Espai Obert, restaurant autogestionat, l''Agenda Llibertària…', '5a3685cf7244b63b82e46f13bd116e54'),
  ('7090fe6b-0d81-4545-a63b-d76a5c2793be', 'Barcelona', 'Spania', 'Fundație de studii libertare și anarhosindicaliste.', 'c9916f3370cc75565f4ded96192662e3'),
  ('72961e3b-901e-4246-a2fd-acb4d4708248', 'Buenos Aires', 'Argentina', 'Bibliotecă populară anarhistă fondată în 1935, încă activă. Arhivă consultabilă, conferințe, ateliere.', '9781294ad6e657aedcbc59cec2affa2b'),
  ('7317c095-c9f4-4f41-b1f0-49a60f4b5476', 'Torino', 'Italia', 'Bibliotecă anarhistă din Torino.', '77d468c3db2667743538ac992c44806a'),
  ('73627648-932a-4e74-ad33-7ca893566eaa', 'Ciudad de México', 'Mexic', 'Centru social autonom anarhist și punk la UNAM, care ocupă Auditorio Justo Sierra (redenumit Che Guevara) din 4 septembrie 2000, după greva studențească din 1999-2000. Găzduiește un infoshop, o cafenea vegetariană, o bibliotecă, o școală de vară pentru copii, ateliere, un radio pirat și o galerie de artă. Autogestionat prin adunare, fără autorități și fără finanțare externă. A respins mai multe tentative de evacuare. NOTĂ: longevitate excepțională (20+ ani), dar activitatea din 2024-2026 neconfirmată de surse recente — de verificat la fața locului înainte de publicare. Sursă: Wikipedia + Radio Zapatista + El Universal.', '18175580e71aea01e4f9c29aa9c6bd9a'),
  ('74c47869-a577-4884-9b7f-ea70dc85d929', 'Imola', 'Italia', 'Arhivă istorică națională a Federazione Anarchica Italiana, la Imola. Membră a rețelei RebAL.', '5d58741340cacad394c8f0412581e2fb'),
  ('75123e2d-da9b-4d1e-ba3b-6eadf0ddff35', 'Lyon', 'Franța', 'Librărie libertară din Lyon, cu tradiție îndelungată. Găzduiește în spațiile sale Centre de Documentation Libertaire (CDL), structură autonomă existentă de la mijlocul anilor 1970, dedicată conservării patrimoniului documentar anarhist și antiautoritar: ~1500 de lucrări, circa o sută de titluri de reviste (1945-2000), câteva mii de afișe, cărți poștale, manifeste și arhive de militanți/militante. Contact CDL: cdllyon@no-log.org.', 'd484b63241404822a478c1e944d96c94'),
  ('765ef9c3-842c-424e-a97a-6da44a2a72fe', 'Berkeley', 'Statele Unite', 'Infoshop și bibliotecă, găzduiește și Alternative Press Collection / Slingshot.', '7a0e28268283f37e9418b1a4cafb18cc'),
  ('76abbd30-334c-40a7-b631-cd32c71b4994', 'Limoges', 'Franța', 'Creat în 2008 în jurul lui Gilbert Roth. Sediul (colecție, arhive) este pe rue du Chinchauvaud; serile, întâlnirile și atelierele au loc la Espace associatif Gilbert Roth (EAGR), 64 avenue de la Révolution, Limoges.', '835068c03e06d720c3f66b04f995ad5b'),
  ('76b958af-2cc2-4a65-b297-428607a756d7', 'München', 'Germania', 'Bibliotecă anarhistă din München, din 2016.', '7c5b525986601d24df139f70df0d4eb4'),
  ('76e5a0c8-9512-439f-9dd7-a02ec3b424cc', 'Atena', 'Grecia', 'Centru social autogestionat în piața Exarchia. Bucătărie socială anarhistă, infokiosk, bibliotecă, arhive locale. Confirmat activ în 2026 în ciuda campaniei de evacuări a guvernului Mitsotakis în cartier, din 2019. Ținte regulate ale atacurilor polițiste și fasciste.', 'a460383fc8314d66a44b397c6101a05e'),
  ('79fa739e-5467-4ed2-8471-c9fa147fe6c1', 'Chicago', 'Statele Unite', 'Librărie radicală și cooperativă de muncă (worker-owned) fondată în 2016, devenită cooperativă în 2020. Politică, teorie radicală, poezie, traduceri, secțiune în spaniolă. Legată activ de mișcările de organizare locală (imigrație, anti-Cop City, dreptul la avort). Supravegheată de FBI ca „loc de întâlnire al extremiștilor anarhiști” (documente Unicorn Riot, 2023). Adresă nouă din 2025 (mutată după creșterea chiriei).', '203c3bfc85991e041121cdd8fb6fba8e'),
  ('7bbef141-dbae-4e59-b2f4-1d543e9cb8ae', 'Montreuil', 'Franța', 'Centru cultural libertar și antifascist autogestionat, la Maison de l''arbre. Găzduiește arhive legate de Armand Gatti și un fond al editurilor militante. Loc de spectacole, întâlniri și lupte.', '2b44680d4e376d4ca42ac2d88ad2120b'),
  ('7d2749b8-26d6-45c3-b0c1-3e48b36ad6c3', 'São Paulo', 'Brazilia', 'Centru de cultură socială anarhistă istoric din São Paulo (fondat în 1933).', 'f05ca093ed823136b949214c7b74d42e'),
  ('7d720083-d651-4fdf-89c6-58fe65447312', 'Cesena', 'Italia', 'Spațiu libertar în Cesena, în memoria lui Edoardo Massari (Sole) și a Mariei Soledad Rosas (Baleno), militanți anarhiști morți în 1998 în circumstanțe legate de represiunea judiciară.', '19227205b3e54c78195230066dd7e563'),
  ('7f6172ca-b403-4747-b5db-fb3f6989e973', 'Belgrad', 'Serbia', 'Centru social antiautoritar și antifascist din Belgrad. Moștenitor al experiențelor Infoshop Furija și ale creșei autogestionate Kokolepo, care existau în squatul Inex-Film (2011-2015, evacuat). Găzduiește un colectiv de booking pentru evenimente antifasciste, un program pentru tineret în legătură cu o comunitate romă vecină, un atelier de serigrafie, un distro de zine-uri și o bibliotecă în dezvoltare. Din rețeaua Balkan Anarchist Bookfair.', '69f1f28460e84afe79dc29d23cac5463'),
  ('7fbee1ab-f578-443a-b4ea-48cd1977af41', 'Medellín', 'Columbia', 'Platformă creativă colaborativă fondată în 2004, dedicată experimentării artistice, culturii libere, autoformării și „Buen Vivir”. A găzduit Feria de Cultura Libertaria de Medellín (organizată de CILEP Medellín, Distribuidora NachoLee și Cruz Negra Anarquista Medellín). Bibliotecă, ateliere audiovizuale, formarea tinerilor din barrio Buenos Aires (comuna 8 și 9). Integrată în Plan Ciudadano de Lectura, Escritura y Oralidad (PCLEO) municipal. Nu strict libertară în sens organic, dar hub de infrastructură de referință pentru scena anarhistă din Antioquia.', '93aff309ef11a580e3a158e3fde082cd'),
  ('802ec8cb-b0ac-4479-9e24-0e9a7b92b7a5', 'Aranjuez', 'Spania', 'Bibliotecă socială libertară.', '9e6cbb62618db3f3691d2960a8c0903a'),
  ('8071c590-0f20-4145-a181-b100b5d8bdd1', 'Bruxelles', 'Belgia', 'Bibliotecă și arhivă anarhistă din Bruxelles.', '8eda079239a735928557ebc8162f75cd'),
  ('8257bf3d-9bc7-47b8-aaa5-c8941c917f62', 'Victoria', 'Canada', 'Infoshop fără scop lucrativ, Victoria (Columbia Britanică).', '6aff7f2f1df60c0f89c71e6d5468dcac'),
  ('8447bf78-9c60-4bc2-8593-e54b5f08240e', 'Poznań', 'Polonia', 'Bibliotecă anarhistă din Poznań.', 'f1e7c0bb17379d61d1e9fb94e7e8e8b4'),
  ('85cae103-d97d-41e2-a081-ddcf5db091f5', 'Appelscha', 'Țările de Jos', 'Arhivă anarhistă pe terenul libertar „Tot Vrijheidsbezinning” din Appelscha (sediul Pinksterlanddagen din 1933). Probabil a doua cea mai mare colecție de publicații anarhiste din Țările de Jos, după IISG. Vizită cu programare în sezon (1 apr.–30 oct.). Membră a FICEDL. Surse: ficedl.info; anarchief.nl / anarchy.be.', '2874e4ce4b1d7e18d4a20ebb85c3fc50'),
  ('8737a1dd-d676-44fd-af69-e0dc274ac600', 'Paris', 'Franța', 'Bibliotecă socială inaugurată în 2024 la ateneul libertar L''Étoile Noire.', '2745319b415986ef8914a02a173ff42a'),
  ('87d51f04-c108-4719-9cdc-05a56349d26b', 'Barcelona', 'Spania', 'Fondat în 1902 în Raval, expulzat în 1939 de trupele franchiste, redeschis în 2018 în același cartier. Centre de Documentació Histórico-Social: ~12 000 de ziare, 25 000 de cărți și numeroase documente despre mișcarea anarhistă și muncitorească. O parte din arhive este încă găzduită la Biblioteca Arús.', 'b0c0c6f6cfc0772fc7b2e055f0b280c9'),
  ('884e14b3-d458-4eb6-b496-6ea5c0bd3251', 'Reggio Emilia', 'Italia', 'Arhivă și bibliotecă a Federazione Anarchica Reggiana, deschisă cu programare. Spațiu separat de Circolo Camillo Berneri (Via Don Minzoni 1/d, care asigură activitățile militante curente ale FAI Reggiana). Reggio Emilia are astfel trei structuri anarhiste distincte: Circolo, această Archivio-Libreria și Archivio Famiglia Berneri (Via Tavolata 6).', 'f78967234cc8df6cf7c59c25204e9129'),
  ('89236370-04ab-46c8-a524-8d68c7c56569', 'Montreal', 'Canada', 'Documentation, Information, Références et Archives. Bibliotecă anarhistă, împrumut gratuit. Aceeași clădire cu librăria L''Insoumise.', '72feda1479cf70bb81918d4b49a3faca'),
  ('8946013f-131b-4e80-b0ac-d179cb498264', 'Köln', 'Germania', 'Bibliotecă și arhivă a mișcărilor sociale de stânga, la Alte Feuerwache.', '02267929383226a418b37de0004e2210'),
  ('8a039b0f-58d6-4c96-8d4e-89477948bde3', 'Dunedin', 'Noua Zeelandă', 'Infoshop anarhist din Dunedin (Ōtepoti), în Te Wai Pounamu (Insula de Sud), fondat în 2003. Librărie fără scop lucrativ, distribuitor de media independente, bibliotecă de referință și arhivă de literatură radicală. Stoc: anarhism, eliberare animală, artă, sexualități queer, lupte indigene (Māori), feminisme, ecologie radicală. Programe libere pe CD. Deschis miercuri 14-17h și vineri 14-20h. Anterior la 24 Stafford St (2003), acum Moray Place. Colaborează cu Dunedin Indymedia.', 'fc890a998848224384817be398aeabff'),
  ('8a1f5500-d0ad-4462-a66c-ee7dd035f08d', 'Milano', 'Italia', 'Bibliotecă a Cascinei autogestionate Torchiera senzacqua, în memoria lui Edoardo Massari (Sole) și a lui Soledad Rosas (Baleno); numele „Bibliotork” este o contracție de Bibliotheca + Torchiera.', 'e272353c73e0e1632987057c151110a6'),
  ('8abac3d1-8f4e-47e5-98ff-1941f5e7d49d', 'Santiago', 'Chile', 'Grup de studiu și difuzare libertară, editura Eleuterio.', 'eb0883e478a2f5ba35c9d9bf698c7612'),
  ('8b5f73a5-5e4f-4942-8287-742445d2fd7a', 'Fano', 'Italia', 'Arhivă-bibliotecă membră a rețelei RebAL.', 'bf3b7bf2499696bfee687a20a221cccb'),
  ('8b8527de-eb01-471d-b230-e26e6176b77f', 'Lyon', 'Franța', 'Librărie libertară, bibliotecă de împrumut, sală de dezbateri și cafenea libertară. Născută în 1989, gestionată de Coordination de Groupes Anarchistes (CGA). Colectivul este proprietarul spațiului de pe rue Diderot din 2011.', '466e329dd6de1d9563d05a5ec64638ca'),
  ('8bba898d-7079-4118-b4aa-dadd6ab8f30c', 'Baltimore', 'Statele Unite', 'Librărie-cafenea și spațiu radical autogestionat în mod cooperativ.', '8d6fb7acee1dc51d96bacaa16a577317'),
  ('8bcc2391-80af-4e4d-8687-fa83a3c360a8', 'Buenos Aires', 'Argentina', 'Sediul istoric al FLA, bibliotecă și arhive ale mișcării libertare argentiniene.', 'edacda57ecde698e1273d259d35da558'),
  ('8cca7569-3480-4222-8e0c-a32273f04f94', 'Berlin', 'Germania', 'Cea mai mare bibliotecă anarhistă publică din Germania (~4000 de cărți, 8000 de reviste). Din 1993. Deschis mier-vin 18-20h.', 'af28c13f7b3c420ba3b92e33b9ab4c11'),
  ('8d33abfc-d40b-4f6b-979c-b9a2931c7b69', 'Napoli', 'Italia', 'Centru de studii libertare în Napoli, cartierul Montesanto.', '82b361c45fb5c34d305d682c29c4ee98'),
  ('8ea175f9-afb6-483f-846d-73371c430cb4', 'Parma', 'Italia', 'Arhivă și bibliotecă a Centro Studi Movimenti din Parma.', '579910fd9c91d829953cadb539a5ee6b'),
  ('8fac3759-2c9d-47b6-8406-e3df68d3f289', 'Havana', 'Cuba', 'Centru social și bibliotecă libertară deschis în 2018 la Havana.', '1d443fa7eee55639bb8eca850f2e97e8'),
  ('9138d6a1-ba4b-4459-97a9-ef6c853eae3b', 'Melbourne', 'Australia', 'Infoshop și librărie anarhistă din Melbourne.', '679088568bd817c60086248aa7f6af57'),
  ('9235f7ec-898f-437b-96f6-517177f7a601', 'Porto Alegre', 'Brazilia', 'Spațiu anarhist autogestionat, proiect de bibliotecă în curs (2026).', '74636868b78e6fe614fa5bbb3e980f0f'),
  ('92cc161b-bec3-4802-8555-9de0ddb0c8f0', 'Montpellier', 'Franța', 'Centru de documentare libertar, catalog integrat în rețeaua RebAL.', 'a993b993dbedd2545304da88f713f7c1'),
  ('92d4af18-ba79-4c79-a449-08211cf9f6ba', 'Marghera', 'Italia', 'Ateneu libertar în Marghera, în periferia industrială a Veneției.', 'ac0675216f2a6c7438e6263b0a7716ee'),
  ('92ebac7d-9189-4583-99e8-eac6b7a5703e', 'Reggio Emilia', 'Italia', 'Cerc anarhist din Reggio Emilia, sediu militant al Federazione Anarchica Reggiana (FAI) și al USI locale. Deschis de luni până sâmbătă, de la 17h la 19h. Distinct de Berneri din Bologna și distinct de Archivio-Libreria a FAI Reggiana (Piazza Magnanini Bondi 1, fișă separată) și de Archivio Famiglia Berneri (Via Tavolata 6, fișă separată).', '91a9c27df8beb26e2dbf12ebad63034b'),
  ('932fc4fc-4734-40bd-a41d-6bb184e35f3b', 'Witten', 'Germania', 'Bibliotecă libertară în centrul sociocultural Trotz Allem, din 2011.', '48c4d2b24c337b9949b19d0aeb404702'),
  ('936bbfa7-9a07-4b6c-a749-492fba9a759e', 'Bruxelles', 'Belgia', 'Bibliotecă anarhistă publică și participativă la Boom Café, în centrul Bruxelles-ului, din 2023. Permanențe-împrumuturi joia 18h-21h, consultare pe loc mier.-dum. 15h-21h. Infokiosk de broșuri și zine-uri. Catalog online pe inventaire.io. Succede librăriilor Zotte Morgen, apoi Acrata. Membră a ABABA, Amicale des Bibliothèques Autogérées de Bruxelles et Alentours (catalog comun pe inventaire.io).', '85a204575b92b7531ab60d737801e7e9'),
  ('947f1222-a7ea-4ad0-bc2c-ae148e70861e', 'Milano', 'Italia', 'Arhivă și centru de studii major. Coordonator al rețelei RebAL.', '0387430eab58928b5bd474659698a4a4'),
  ('94936a1b-a8c0-4f9a-9c2f-f2e486749778', 'Lyon', 'Franța', 'Centre Michel Derrion. Documentare despre alternativele sociale și autogestiune.', 'c467e844b2e1cbb71e71418b9b5e9fb5'),
  ('95a38b74-509b-4eb5-9148-731cae3eac99', 'Auckland', 'Noua Zeelandă', 'Singurul infoshop/opshop anarhist din Auckland (Tāmaki Makaurau), situat pe Karangahape Road (K'' Road), principalul cartier LGBTQ+ și cultural al orașului. NOTĂ: activitatea din 2024-2026 nu este confirmată explicit de surse recente — site-ul anarchism.nz, care agregă scena, nu-l mai listează printre proiectele active (care includ Black Star Books Dunedin, Beyond Resistance, AWSM, Garage Collective). Fișă de coroborat prin contact direct sau prin compañerxs de la fața locului înainte de publicare.', 'f947ce3dff9a4ce9bacb9b9b826a23a5'),
  ('96806502-fe53-4d55-9b34-132fdaa9ce1c', 'Fano', 'Italia', 'Arhivă membră a rețelei RebAL.', 'b7b28c958727eb17d0ca88034ecfbf01'),
  ('9819c089-7571-45d2-9f53-392cf823c588', 'Ragusa', 'Italia', 'Arhivă istorică a anarhiștilor sicilieni, la Ragusa.', 'd8aba3821b7d15fc2b9ae160639133d2'),
  ('98719466-65f1-4884-b16d-7f400057a86b', 'Ciudad de México', 'Mexic', 'Una dintre cele mai mari biblioteci anarhiste din America Latină, fondată în 1978 de anarhistul catalan exilat Ricardo Mestre Ventura (1906-1997), veteran al CNT-FAI și al Revoluției spaniole. Fond de +3000 de cărți (Flores Magón, Proudhon, Bakunin, Kropotkin, Reclus), 600 de periodice rare (La Revista Blanca, Regeneración 1900, La Protesta). Ediciones Reconstruir. Condusă de Tobi Libertario din 1997 până la moartea sa (covid, ian. 2021). Redeschisă în ian. 2015 la adresa actuală. Sursă: Wikipedia + Proceso + site oficial.', '40865e19abc87d0ffea878f21bc400ba'),
  ('99849ffc-4e19-49d9-b417-78d47efee8e2', 'Halifax', 'Canada', 'Bibliotecă de fanzine din Halifax, integrată în spațiul Radstorm (cu Inkstorm Screenprinting și SADRAD). Fond de zine-uri, program de rezidențe de creație (Zinefest Residency din 2020), organizează Halifax ZineFest. Spațiu autogestionat de cultură DIY și antiautoritară. Sursă: Kersplebedeb + Wikipedia (Radstorm).', '88b791d2f460c25b51dadb986af79db7'),
  ('99e327cd-0e21-4c7f-b573-d1d36222deb9', 'Roma', 'Italia', 'Bibliotecă anarhistă la Roma.', '8df7a1c57262410c3b9c92c4d208e8a8'),
  ('9cda3d54-be40-4ba7-924f-42466d008d7f', 'Londra', 'Regatul Unit', 'Cea mai veche editură anarhistă anglofonă (1886), librărie și spațiu de întâlniri.', 'b70264e9dfe2acbd046b6e7a548f86f2'),
  ('a012f5aa-4205-44c7-a3af-b84aa9d1998e', 'Aversa', 'Italia', 'Librărie militantă în Aversa, în Campania.', 'be70fd2348a2f2cc83ee9b7710244ca3'),
  ('a2927419-0cce-4216-b3bc-8092fd519495', 'Bologna', 'Italia', 'Spațiu de documentare anarhistă la Bologna.', '324790e7491f0a918b55b19b9ff15e5e'),
  ('a3cfecc3-a9a1-40c9-ad8c-c63fee30611d', 'Roma', 'Italia', 'Arhivă a mișcărilor sociale la Roma, cartierul Tor Pignattara.', '0d1b27b070929ff0ee4f8666dd82c826'),
  ('a4108981-a505-4774-b973-6abf86d75e50', 'Sydney', 'Australia', 'Librărie și bibliotecă anarhistă din Sydney, din 1977.', '9ae06ba60a663940c118317a6d97c328'),
  ('a5a5ee8b-111e-4456-a0ee-878cdb21f6be', 'Santiago', 'Chile', 'Bibliotecă anarhist-nihilistă din Santiago, în memoria lui Sebastián „Pelao Angry” Oversluij Seguel, anarhist ucis pe 11 decembrie 2013 în timpul unei exproprieri. Spațiu ocupat. Activități regulate: cineforumuri, conversatorios, propagandă, bucătărie vegană. Adresa este comunicată prin e-mail din motive de securitate.', '4e0ad169079e6ba2276d5af860cb6ed3'),
  ('a6818381-72aa-4d6d-8bd3-3919a5cdf76d', 'Mendoza', 'Argentina', 'Ateneu anarhist din Mendoza, punct de distribuție al rețelei anarquista.info. Adresa exactă nu este dezvăluită.', '39fdbfa8e536b66915f304f9247fc666'),
  ('aa03adfd-8125-4842-8a10-6e2097656d37', 'Boston', 'Statele Unite', 'Cel mai vechi infoshop din Statele Unite (1969). Librărie radicală și centru social autogestionat.', 'd8f92d358a3000132d5f47ce682b3453'),
  ('aa740163-0093-459e-8562-8bacf91cc1e3', 'Gent', 'Belgia', 'Centru anarhist (anarchistisch centrum) deschis în cartierul Brugse Poort din Gent. Inima ecosistemului libertar din Gent: găzduiește la aceeași adresă Anarchistische Infotheek (bibliotecă) la etajul 1 și Anarchief (cea mai mare arhivă anarhistă din Belgia). Cantină populară (volkskeuken) miercuri la 20h și vineri la 19h, cineclub lunar, QuAttack (prima miercuri a lunii), conferințe, dezbateri, prezentări de carte. Animat de Assez Collectief, în legătură cu Anarchistisch Kollektief Gent. Surse: acgent.org, anarchie.be/ac.', '0dfded7924e01c265d8e1da9afda8970'),
  ('ab0a3d9a-da3a-4d8c-a6d7-d3139edb335c', 'Pisa', 'Italia', 'Bibliotecă-arhivă și editură (BFS Edizioni). Istorie socială și mișcarea libertară. Situată la Ghezzano (comuna San Giuliano Terme), la periferia orașului Pisa.', 'd2a61f69ca7807204858e66ed32b7e3a'),
  ('abbe5586-9cbd-46db-a5cd-c193d80752e1', 'Salonic', 'Grecia', 'Spațiu libertar (eleftheriako steki) deschis pe 25/04/2025 de colectivele care ocupau katalipsi-ul istoric Libertatia (squat din 2008, incendiat de fasciști în 2018, evacuat de două ori în 2024). Găzduiește grupul Bibliotecă, Traduceri și Autoformare „Contra Texto”, o structură de librărie autogestionată (în fiecare miercuri 18h-22h, zeci de edituri, printre care ed. Nowa Kultura), prezentări de carte, cineclub, bucătării colective, adunări de solidaritate. Rezistență–autogestiune–solidaritate. NOTĂ: ținta unui atac fascist cu dispozitiv exploziv pe 24/02/2026 (manifestație de solidaritate pe 14/03/2026) — loc viu, dar sub presiune. Surse: victoire.noblogs.org, infolibre.gr, anarxiki-omospondia.gr, anarchistnews.org.', '85f3b34cb5cb9c8da1d2ac485f634490'),
  ('ad7951f3-d705-4144-a775-55b837171351', 'Madrid', 'Spania', 'Bibliotecă + arhive ale CNT, ~5000+ cărți. Arhivă la Yuncler (Toledo). Referință mondială pentru anarho-sindicalism.', 'c3c11b0c2474c1d540d257cd0d132789'),
  ('b1a476f9-5733-4ecc-b0ae-77376acbbad9', 'New York', 'Statele Unite', 'Colectiv cultural autogestionat fondat în 1980 într-un squat de pe 156 Rivington. Clădire istorică demolată în 2017, o nouă clădire cu 4 etaje în construcție pe același amplasament, **redeschidere prevăzută în vara/toamna lui 2026** (finanțare de 21 M$ de la departamentul de afaceri culturale al NYC). Va cuprinde zine library, atelier de serigrafie, studio de înregistrări, galerie, spații pentru program de evenimente. Steven Englander, directorul istoric, a decedat în decembrie 2024.', '33bf709cb08a3cdbd39b83e734039e5b'),
  ('b596592f-6d41-4148-b837-03c182b8a728', 'Praga', 'Cehia', 'Infocentru anarhist deschis în ianuarie 2012 în Žižkov, numit după portul pirat marocan Salé (secolul al XVII-lea), teritoriu independent economic, politic și intelectual. Freeshop, bibliotecă anarhistă, librărie, spațiu pentru colective antiautoritare, mese vegane.', '841e5808b122cec39ef86ce53bb59ddb'),
  ('b598eaf9-613f-4650-8dc3-fcf436cba0ad', 'Florența', 'Italia', 'Arhiva Mișcării de cartier din Florența.', '3d2fe716148df54d7243e3d830b4ce2f'),
  ('b606f74b-9657-4455-91fa-6c5a301efba1', 'Roma', 'Italia', 'Bibliotecă anarhică fondată în 1995 de individualități anarhiste, în cartierul Pigneto. Păstrează Archivio Internazionale di Controcultura del Movimento Operaio — peste 10 000 de texte (cărți, broșuri, periodice, afișe, documente), dintre care unele datează de la începutul secolului al XX-lea. Spațiu autogestionat colectiv după principiul unanimității, în afara oricărui grup politic. Distribuție de material libertar autoprodus, publicații periodice. Permanențe marți și vineri de la 17h. Situație precară din 2019 (risc de evacuare legat de gentrificarea din Pigneto, campanii anuale de autofinanțare). Ultimul apel datat 29 iulie 2025.', '58f1d34594d2bad20a94da1b075f47fa'),
  ('b63b7446-5d04-4e8f-8b27-b72991d28575', 'Córdoba', 'Argentina', 'Bibliotecă anarhistă din Córdoba (Argentina), punct de difuzare a presei și a edițiilor libertare.', 'ad0e34bc1a1ab4933ae6554f8c04eaba'),
  ('b83a4cd7-5a3b-4f1d-b4b9-f21f6e7b7d71', 'Hamburg', 'Germania', 'Arhivă regională de documentare a socialismului antiautoritar.', 'b7fd926b94d7b50dd0bb00d562fb31a6'),
  ('b840d66b-4846-4123-8943-f7fb8ff3e604', 'Kathmandu', 'Nepal', 'Mică bibliotecă anarhistă cu acces liber, deschisă în 2024.', '5d513bbd0f460bee4b135ec7af2c9129'),
  ('bc0fe2fb-9698-4362-bdd2-da754978f2f9', 'Toulouse', 'Franța', 'Centru de documentare despre luptele sociale și mișcarea libertară.', '5471643e68785a69cf409cef1fb676b1'),
  ('bddd0519-2a0b-4a24-af55-18a9c34a3f17', 'Amsterdam', 'Țările de Jos', 'Instituție majoră: cea mai importantă colecție de arhive anarhiste din lume (fondurile Bakunin, Nettlau, CNT...).', 'e9953e5899b46a47b3092163bdbbf04c'),
  ('bed35ce3-6f39-4c39-9367-95b44fae06a7', 'Roma', 'Italia', 'Bibliotecă anarhistă autogestionată, cartierul Centocelle.', 'b73a89f70e5044256f48dfdd51621daf'),
  ('bf92609b-e322-492c-b75c-c3578e5c8a2a', 'Imperia', 'Italia', 'Centru de documentare la Imperia.', '4fcfe7653ac073bd378ee77237b1e0b1'),
  ('c094a30f-4507-46bb-bd25-9746dbfe3d0d', 'Berkeley (California)', 'Statele Unite', 'Colecția fizică principală (~10 000 de volume), în California din 1999. Consultare cu programare.', '45e307039f6e7cebbd11eabefcb398d6'),
  ('c0a76bb0-51f6-4283-bc7a-f51c7d97b604', 'Buenos Aires', 'Argentina', 'Bibliotecă și librărie populară cu limbaj incluziv, San Telmo.', 'b8c9c8b35c5ef414ef7bc4613e0eb970'),
  ('c1ed61b6-65cc-4a99-a3f9-5a3db8ee0813', 'Valparaíso', 'Chile', 'Bibliotecă anarhistă din Valparaíso, găzduită la Espacio Katarcis. Numele este un omagiu adus Luisei Toledo Sepúlveda (1939-2021), mama fraților Vergara Toledo asasinați de Carabineros în timpul dictaturii, icoană a memoriei combative chiliene. Menționată de La Peste (februarie 2023). Miercuri 20h. Spațiul Katarcis este deschis marți 17-20h și joi 17-20h, ca punct de sprijin pentru compañerxs din închisoare. Activă în 2025 (punct de colectare pentru Felipe Ríos, iulie 2025). IG @sala_luisatoledo.', 'dafc2c781d78cf714b1a70cddea9f095'),
  ('c27f6d55-a307-4dd4-b895-182fd93e92c9', 'Pordenone', 'Italia', 'Bibliotecă membră a rețelei RebAL.', '7a3517ce2e59a1198d93252c09d294b5'),
  ('c2c672f3-56a3-42a1-af5e-cdbffdee4bb7', 'La Paz', 'Bolivia', 'Casă autogestionată a colectivului anarha-feminist Mujeres Creando (fondat în 1992 de María Galindo, Mónica Mendoza și Julieta Paredes). La Virgen de los Deseos este spațiul lor permanent din La Paz: bibliotecă, restaurant, cafenea, librărie, program politic și cultural. Emite Radio Deseo (103.3 FM) din 2007. Gazdă a ziarului Mujer Pública și a numeroase publicații. Recunoscut drept „singurul spațiu feminist din La Paz” de colectivul însuși. Referință internațională a feminismului anarhist latino-american („indias, putas y lesbianas, juntas, revueltas y hermanadas”, María Galindo).', 'e0a457625314cdf0dd1a2d357f318358'),
  ('c46186cd-871c-46ec-8a87-92d4e02d0b5a', 'São Paulo', 'Brazilia', 'Bibliotecă anarhistă fondată în 2009. Foarte activă: ediții, dezbateri, congres internațional de cercetare despre anarhism (2022).', 'a52c48f1b4aea9fc057ae5db3b181eef'),
  ('c5c10c1f-b51d-4024-aba4-4495fbd9f92a', 'Buenos Aires', 'Argentina', 'Bibliotecă anarhistă din cartierul Saavedra (nordul orașului Buenos Aires), găzduită la La Huerta De Saavedra. Punct de distribuție al rețelei anarquista.info și al ziarului Gatx Negrx.', '7e7b3a84f92470a4c4d46e4ca09f9bbe'),
  ('cb327875-7a98-48f2-aa45-1ebcd1f25737', 'Salvador', 'Brazilia', 'Spațiu libertar din Salvador: bibliotecă (fond anarhist clasic), grup de studiu despre anarhism, proiecții, întâlniri. Instalat într-un loc istoric al mișcării punk și anarhiste din oraș. Moștenește Biblioteca Emma Goldman, născută în 1994 în cadrul Associação em Prol do Pensamento Libertário (APPL). Membru al rețelei AnarBib.', 'e2a35f6b660a78628ca0b3032fe13ee8'),
  ('cb685e1e-3d39-47d9-b151-61080a11a872', 'Belém do Pará', 'Brazilia', 'BLMF — Biblioteca Libertária Maxwell Ferreira, susținută de Centro de Cultura Libertária da Amazônia (CCLA), la Belém do Pará. Membră a rețelei AnarBib.', '917178c5284ffbe54ab1c5716897a40b'),
  ('cb9debf9-765f-4276-8a39-3a601fab582b', 'Giano dell''Umbria', 'Italia', '„Republica Frigolandia”: proiect de artă, contracultură și documentare legat de revista Frigidaire a lui Vincenzo Sparagna, în Umbria.', 'ca9f294e5c10583294a63aaa699b8560'),
  ('cd49c8a8-5c32-45c4-95c0-35d24d37bfd4', 'Carrara', 'Italia', 'Arhivă anarhistă din Carrara, regiune cu o puternică tradiție libertară. Găzduită în fostele școli Domenico Guidi din Torano.', '78818b152664e1a3d01263d6bddae8cb'),
  ('cd5ef6cb-1ecd-4b3a-90fd-b5238549e31c', 'Rimini', 'Italia', 'Bibliotecă anarhistă la Rimini, numită după Albert Libertad, anarhist individualist francez de la începutul secolului al XX-lea.', 'e7d5b1f3adfb95e17a56d3fe44a2546c'),
  ('ceb1d3a7-5af9-42f0-824f-c169d90e3315', 'Genova', 'Italia', 'Bibliotecă libertară din Genova, rețeaua RebAL.', 'f517b781d927381f92839ae83ea29539'),
  ('d0df6630-e342-44b0-80d0-dc1b521d5bf9', 'Sherbrooke', 'Canada', 'Arhive militante din Estrie + bibliotecă anarhistă și decolonială.', 'e0a33648ba7b6c930bdd181816a1a84d'),
  ('d2e1c274-fc5e-4890-aa86-7ef6209f622f', 'Torino', 'Italia', 'Centru de documentare la Torino.', '28aa17cec3dcb2b57e9bde1634200bad'),
  ('d47321a5-cc4b-407d-a114-b28d7a70ac70', 'Budapesta', 'Ungaria', 'Centru cultural și comunitar fondat în 2014 în sectorul 8 al Budapestei, model de democrație participativă. Hub de ONG-uri (Roma Press Centre, Budapest Pride, School of Public Life, Atlatszo…), spațiu pentru colective marginalizate. Țintă recurentă a guvernului Fidesz și a extremei drepte Légió Hungária (atacul din 23 octombrie 2019).', 'b1fa37e7f14746b6e950e4835fa481d8'),
  ('d4edc130-4d24-4ab4-be7a-f9184f8139c5', 'Sabadell', 'Spania', 'Ateneu libertar din Sabadell, în localul de patrimoniu recuperat de CNT Sabadell. Spațiu de întâlnire, formare, memorie istorică și solidaritate. Cont de organizație @ateneullibertarisbd activ.', '91d1362d604d116cd6b2caaac16e953e'),
  ('d5194242-512c-4917-b2ed-2f985e4c4c10', 'Genova', 'Italia', 'Librărie libertară la Genova.', '1b1ab3fb74ffe540285d362f964b7d0c'),
  ('d5555b17-0095-4476-853e-fe50fc114d28', 'Barcelona', 'Spania', 'Bibliotecă centenară, ~65 000 de volume despre anarhismul spaniol, francmasonerie, mișcarea muncitorească.', '3a6f7c97152d1ab2e4135b1a368b5804'),
  ('d64fdb2a-485d-4a7e-88bd-2f613b4bb409', 'La Plata', 'Argentina', 'Biblioteca Casei Zaragoza din La Plata. Punct de distribuție al ziarului Gatx Negrx. Prezență online aproape nulă, activitate 2024-2026 neconfirmată independent — fișă de verificat prin contact direct.', '7af5cf1741c509694d68f73d40567ca8'),
  ('d6d368a0-e085-47c6-a64f-79b65cfc0480', 'Praga', 'Cehia', 'Centru comunitar autogestionat în cartierul Nusle din Praga, deschis din septembrie 2024. Găzduiește Radical Library, transferată de la Klinika (squat evacuat în 2019), o arhivă de zine-uri și periodice alternative, un distro al AF Publishing. Spațiu de întâlniri, evenimente publice, sprijin pentru mișcările antiautoritare.', '74d943e786814d5508e5707e40292f7f'),
  ('d9e653a6-07b2-4d1e-a6be-39ad36e1ec0e', 'Lisabona', 'Portugalia', 'Librărie de referință apropiată de mediile libertare din Lisabona.', '0a95674c3c6dbd58fcb8a2f0b26ccdc3'),
  ('dbc59ff3-5c97-446c-9943-ab8b05618880', 'Fujinomiya', 'Japonia', 'Filiala japoneză a CIRA (centrul internațional de cercetări despre anarhism), la Fujinomiya (Shizuoka). Continuă CIRA-Nippon (Kobe, 1974–1980). Fond de aproximativ 2000 de cărți, broșuri și periodice, cu o casă care servește drept sală de lectură. Membră a FICEDL. Surse: en.wikipedia.org (CIRA); libcom.org (Libero International).', '29ee2b8ef868fb00a5ee575a24a1c2d2'),
  ('dc010dba-2b77-4ada-8015-da6f7c2d03e9', 'Palma de Mallorca', 'Spania', 'Ateneu libertar din Insulele Baleare, fondat în 1992. Editează revista Estel Negre din 1989. Bibliotecă, arhivă și conferințe (Jornades Libertàries). Adresă poștală: Apartat 1566, 07080 Palma.', 'f632ecaf116d5180b2f5acb59404d5fb'),
  ('e11a8159-6fe7-4972-a28a-5a24112964d0', 'Lille', 'Franța', 'Local care găzduiește biblioteca pentru consultare și împrumut a CCL din Lille, fondat în anii ''80, al cărui sediu istoric de la 4 rue de Colmar este încă activ.', '85bf6bf8506f8c10e04abc2f41bb2a11'),
  ('e19492ed-9511-4925-99ca-d007643ef9f9', 'Utrecht', 'Țările de Jos', 'Infoshop cu bibliotecă, colectiv anarhist din Utrecht.', '061f3a1e9d4ba2903537d7c459e7e3fb'),
  ('e1bb2f36-03cd-4994-a54c-9e45168c849e', 'São Paulo', 'Brazilia', 'Centru de documentare universitar, fonduri importante despre anarhism și mișcarea muncitorească braziliană.', '9f521ff27e38157dfcd56cdae9f0c27b'),
  ('e596bae5-8562-4a90-b743-17742ef87843', 'Asheville', 'Statele Unite', 'Librărie cooperativă și spațiu comunitar radical.', '55a9aa9c677f66aa4265e52ff9acaf0c'),
  ('e6df1ac2-d051-41db-93c5-7046da735557', 'Rio de Janeiro', 'Brazilia', 'Fondată în 2001. Acervo provenit de la CELIP, găzduiește Núcleo de Pesquisa Marques da Costa. În cadrul CCS-RJ.', '4b154bceaca936f0495636ced7777cb9'),
  ('e78016fa-81c9-4ee6-95a2-6564f0f18ceb', 'Montevideo', 'Uruguay', 'Arhivă-bibliotecă dedicată memoriei libertare, care poartă numele militantei și istoricei Luce Fabbri.', '520be8e7f5f7ecbb70e8966251936bc6'),
  ('e8c22caa-54f3-4a53-a67b-ee91249e6a97', 'Bologna', 'Italia', 'Centru de documentare al mișcărilor sociale, în memoria lui Francesco Lorusso (militant ucis de poliție în 1977 la Bologna) și a lui Carlo Giuliani (ucis de carabinieri la Genova în 2001, în timpul G8). Spațiu social autogestionat.', '906ef9009e1a8e88bc9868c04d1b4b66'),
  ('eaec71f1-ffdf-4928-aa8e-9c188e3c955c', 'Valparaíso', 'Chile', 'Bibliotecă anarhistă din Cerro Playa Ancha, Valparaíso. Menționată de La Peste (februarie 2023) printre bibliotecile populare și antiautoritare din regiune. Deschisă joia 16-20h. Adresa exactă nu este publicată din motive de securitate. IG @biblioteka.akantilado.', '5d2d9a7464994f7c39b7dd3026b03ef5'),
  ('f043a8d6-a55a-4839-ae30-1c5e418a20ee', 'Almada', 'Portugalia', 'Ateneu anarhist fondat în 1974 la Cacilhas de foști militanți libertari care rezistaseră dictaturii. Peste 50 de ani de activitate neîntreruptă pe malul sudic al Tajo. Găzduiește o bibliotecă și o librărie deschise publicului, un fond documentar important, activități publice regulate, loc de întâlnire și de convivialitate antiautoritară. Organizare prin adunări, fără funcții de conducere; cheltuieli acoperite din cotizații, donații, cine și vânzarea de publicații. După ani de amenințări cu evacuarea și de presiune a gentrificării, CCL a reușit în 2026 să cumpere un local lângă Bairro Amarelo, în apropierea gării Pragal, la Almada — sfârșitul dependenței de proprietar. Campanie de solidaritate în desfășurare (70 000 € de strâns pentru datorie și lucrări). Sediul din Cacilhas va continua să funcționeze până în 2029. NOTĂ: punct cartografiat într-o zonă aproximativă (adresa exactă a noului local nu este publicată pe durata campaniei). Sursă: comunicatul CCL, 2026.', 'e20c2d936a1a3fb2af2c27a63314d0fd'),
  ('f098b4a1-3962-4f8b-92d1-409f81b05ae3', 'Hamburg', 'Germania', 'Bibliotecă libertară a centrului cultural și de acțiune Schwarze Katze.', 'a3f961369125a2d6e5f14953b6738159'),
  ('f4efbff3-2a65-4d98-a658-989401b16316', 'Lecce', 'Italia', 'Bibliotecă anarhistă la Lecce. A nu se confunda cu Biblioteca Anarchica Disordine din Torino (colectiv distinct).', '277b70f03e4516de9fb575546736242c'),
  ('f55e29cb-5d43-4e34-a8fc-9c7f6bf8625b', 'Olympia', 'Statele Unite', 'Librărie underground din Olympia, fondată în 2002 de studenți de la Evergreen State College. Fond de cărți la mâna a doua și rarități, găzduiește Olympia Zine Library și o editură independentă. Secțiuni de activism, contracultură, ecologie, DIY. Reputație anarhistă locală. Lun-Sâm 11h-19h. Sursă: ThurstonTalk + Yelp (activă în dec. 2025).', 'f9cec0ad23cdb36f3572341ca7b5f7d8'),
  ('f56b9af5-193d-4de2-aa2c-42603985c22f', 'Asunción', 'Paraguay', 'Bibliotecă anarhistă din Asunción. Numele său amintește de El Despertar, primul ziar muncitoresc anarhist din Paraguay (1906-1907). Adresa exactă rămâne de confirmat.', 'a590da21e9f116d396936f3791d6c5b2'),
  ('f64b7ef6-fba4-4ef1-92f6-81bfb16d91f1', 'Jesi', 'Italia', 'Centru de studii libertare, rețeaua RebAL. Adresa actuală: Viale Pastrengo 2B (mutare în urma mai multor evacuări, inclusiv de la adresa istorică Via Posterma).', '184220116b3194531f22a5906297f27d'),
  ('f75f6f45-1d19-4963-990e-105f6b9a4115', 'Madrid', 'Spania', 'Ateneu cooperativ din cartierul Lavapiés.', '385c0e2d2b7251dba585789ef8821742')
) AS v(id, ville, pays, note, empreinte)
WHERE c.id = v.id::uuid
  AND NOT (c.name_i18n ? 'ro')
  AND md5(concat_ws(E'\x01', coalesce(c.city_i18n->>'fr', ''), coalesce(c.country_i18n->>'fr', ''), coalesce(c.notes_i18n->>'fr', ''))) = v.empreinte;

