-- ── Vérification : en production tout est traduit ; ailleurs, rien n'est faux ──
DO $verif$
DECLARE
  n_carto int; n_carto_ro int; n_th int; n_th_ro int; n_suj int; n_suj_ro int;
  n_sugg int; n_sugg_ro int; n_rec int; n_rec_ro int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE name_i18n ? 'ro') INTO n_carto, n_carto_ro FROM public.cartography_entries WHERE name_i18n ? 'el';
  SELECT count(*), count(*) FILTER (WHERE labels_proposes ? 'ro') INTO n_th, n_th_ro FROM public.ficedl_thesaurus_terms WHERE labels ? 'el';
  SELECT count(*), count(*) FILTER (WHERE label_i18n ? 'ro') INTO n_suj, n_suj_ro FROM public.subjects WHERE label_i18n ? 'el';
  SELECT count(*), count(*) FILTER (WHERE title_i18n ? 'ro') INTO n_sugg, n_sugg_ro FROM public.painel_task_suggestion_catalog WHERE title_i18n ? 'el';
  SELECT count(*), count(*) FILTER (WHERE title_i18n ? 'ro') INTO n_rec, n_rec_ro FROM public.painel_recurring_task_rules WHERE title_i18n ? 'el';
  RAISE NOTICE 'roumain des données : carte %/%, thésaurus %/%, sujets %/%, suggestions %/%, récurrentes %/%',
    n_carto_ro, n_carto, n_th_ro, n_th, n_suj_ro, n_suj, n_sugg_ro, n_sugg, n_rec_ro, n_rec;
  IF EXISTS (SELECT 1 FROM public.ficedl_thesaurus_terms WHERE labels ? 'ro' AND labels_proposes ? 'ro') THEN
    RAISE EXCEPTION 'thésaurus : une proposition doublerait un libellé de la source';
  END IF;
  IF EXISTS (SELECT 1 FROM public.cartography_entries WHERE name_i18n ? 'ro' AND name_i18n->>'ro' IS DISTINCT FROM name_i18n->>'fr') THEN
    RAISE EXCEPTION 'carte : un nom propre a été traduit';
  END IF;
END
$verif$;
